effects.css:
@keyframes sl-pat-dg-base {
  0%, 100% { transform: translate3d(0,0,0); filter: none; }
  4%       { transform: translate3d(-2px, 1px, 0); filter: hue-rotate(20deg) saturate(1.4); }
  8%       { transform: translate3d(0,0,0); filter: none; }
  42%      { transform: translate3d(3px, -1px, 0); filter: hue-rotate(-15deg); }
  46%      { transform: translate3d(0,0,0); filter: none; }
  78%      { transform: translate3d(-3px, 0, 0); filter: hue-rotate(25deg); }
  82%      { transform: translate3d(0,0,0); filter: none; }
}
@keyframes sl-pat-dg-slice-a {
  0%, 100% { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  4%       { transform: translate3d(-10px, 0, 0); clip-path: inset(20% 0 55% 0); opacity: 0.9; }
  9%       { transform: translate3d(8px, 0, 0);  clip-path: inset(60% 0 15% 0); opacity: 0.9; }
  13%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  42%      { transform: translate3d(12px, 0, 0); clip-path: inset(35% 0 40% 0); opacity: 0.9; }
  46%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  78%      { transform: translate3d(-14px, 0, 0); clip-path: inset(70% 0 10% 0); opacity: 0.9; }
  83%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}
@keyframes sl-pat-dg-slice-b {
  0%, 100% { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  6%       { transform: translate3d(11px, 0, 0); clip-path: inset(50% 0 30% 0); opacity: 0.85; }
  10%      { transform: translate3d(-9px, 0, 0); clip-path: inset(15% 0 70% 0); opacity: 0.85; }
  14%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  40%      { transform: translate3d(-13px, 0, 0); clip-path: inset(65% 0 20% 0); opacity: 0.85; }
  44%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  76%      { transform: translate3d(10px, 0, 0); clip-path: inset(25% 0 60% 0); opacity: 0.85; }
  80%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}
.succy-label-pattern-inner[data-pattern-anim="display_glitch"]::before {
    opacity: 0;
    filter: hue-rotate(160deg) saturate(2.2);
    mix-blend-mode: screen;
    animation: sl-pat-dg-slice-a calc(var(--sl-pat-dur, 2s) * 1.6) steps(1, end) infinite !important;
}
.succy-label-pattern-inner[data-pattern-anim="display_glitch"]::after {
    opacity: 0;
    filter: hue-rotate(280deg) saturate(2.2);
    mix-blend-mode: screen;
    animation: sl-pat-dg-slice-b calc(var(--sl-pat-dur, 2s) * 1.9) steps(1, end) infinite !important;
}

@keyframes sl-pat-gg-base {
  0%, 100% { transform: translate3d(0,0,0); filter: none; }
  8%       { transform: translate3d(-2px, 0, 0); filter: hue-rotate(15deg) saturate(1.4); }
  9%       { transform: translate3d(0,0,0); filter: none; }
  47%      { transform: translate3d(3px, 0, 0); filter: hue-rotate(-12deg); }
  48%      { transform: translate3d(0,0,0); filter: none; }
  81%      { transform: translate3d(-3px, 0, 0); filter: hue-rotate(20deg) saturate(1.6); }
  82%      { transform: translate3d(0,0,0); filter: none; }
}
@keyframes sl-pat-gg-slice-a {
  0%, 100% { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  7%       { transform: translate3d(-24px, 0, 0); clip-path: inset(22% 0 55% 0); opacity: 1; }
  11%      { transform: translate3d(20px, 0, 0);  clip-path: inset(58% 0 18% 0); opacity: 1; }
  14%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  46%      { transform: translate3d(22px, 0, 0);  clip-path: inset(35% 0 40% 0); opacity: 1; }
  49%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  78%      { transform: translate3d(-26px, 0, 0); clip-path: inset(70% 0 12% 0); opacity: 1; }
  82%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}
@keyframes sl-pat-gg-slice-b {
  0%, 100% { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  5%       { transform: translate3d(20px, 0, 0);  clip-path: inset(50% 0 32% 0); opacity: 1; }
  9%       { transform: translate3d(-17px, 0, 0); clip-path: inset(14% 0 72% 0); opacity: 1; }
  12%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  44%      { transform: translate3d(-24px, 0, 0); clip-path: inset(65% 0 22% 0); opacity: 1; }
  47%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
  76%      { transform: translate3d(18px, 0, 0);  clip-path: inset(28% 0 58% 0); opacity: 1; }
  80%      { transform: translate3d(0,0,0); clip-path: inset(0 0 0 0); opacity: 0; }
}
.succy-label-pattern-inner[data-pattern-anim="display_glitch_v2"]::before {
    opacity: 0;
    mix-blend-mode: difference;
    animation: sl-pat-gg-slice-a 3.4s steps(1, end) infinite !important;
}
.succy-label-pattern-inner[data-pattern-anim="display_glitch_v2"]::after {
    opacity: 0;
    mix-blend-mode: difference;
    filter: hue-rotate(180deg) saturate(1.8);
    animation: sl-pat-gg-slice-b 4.1s steps(1, end) infinite !important;
}
